#!/usr/bin/env bash
# 수집 스크립트가 어떻게 끝났는지 보고, 「실패」와 「닿지 않음」을 가릅니다.
#
# ★ 〔2026. 9. 2.〕 왜 가르는지.
#
#   KOSIS 가 한 번 안 열렸다고 정기 갱신 전체가 죽고 「Run failed」 메일이
#   왔습니다. 그런데 자료가 틀린 것도, 우리가 잘못한 것도 아니었습니다.
#   방화벽이 그 러너의 IP 를 통째로 버린 것이었습니다 — 2분 뒤 같은 코드로
#   다시 돌리니 1.7초 만에 됐습니다.
#
#   이것을 실패로 치면 고칠 수 없는 일로 매달 메일이 옵니다. 그렇다고 조용히
#   넘기면 자료가 언제부터 낡았는지 아무도 모릅니다. 그래서 이렇게 합니다.
#
#     닿지 않음(75) → 경고로 남기고 이름을 적어 둡니다. 워크플로가 그 이름만
#                     골라 «새 러너»에서 한 번 더 돌립니다. IP 가 바뀝니다.
#     그 밖의 실패   → 그대로 실패입니다. 사람이 봐야 하는 일입니다.
set -uo pipefail

name=$1
code=$2

if [ "$code" = "0" ]; then
  exit 0
fi

if [ "$code" = "75" ]; then
  echo "::warning::${name} — 서버에 닿지 않았습니다. 러너 IP 가 막힌 것으로 보입니다. 지금 있는 자료를 그대로 두고, 새 러너에서 한 번 더 해 봅니다."
  echo "BLOCKED=${BLOCKED:-} ${name}" >> "$GITHUB_ENV"
  exit 0
fi

echo "::error::${name} — 종료코드 ${code}. 닿지 않은 것이 아니라 실제로 탈이 났습니다."
exit "$code"
